'use strict';
// Each completed step awards one star; revisiting never duplicates it.
const TOTAL=50;
let adventureSeed;
try{adventureSeed=Number(localStorage.getItem('patos-adventure-v3'));}catch{}
if(!Number.isInteger(adventureSeed)||adventureSeed<=0){adventureSeed=Math.floor(Math.random()*4294967294)+1;try{localStorage.setItem('patos-adventure-v3',String(adventureSeed))}catch{}}
const factory=ChallengeFactory.generator(adventureSeed),variantNames=ChallengeFactory.variantNames;
const levels=factory.deck(),visited=new Set();
const typeNames={different:'Encuentra',count:'Observa',memory:'Recuerda',arithmetic:'Calcula',pattern:'Descifra',logic:'Deduce',code:'Resuelve'};
const $=id=>document.getElementById(id);let completed=new Set();try{const saved=JSON.parse(localStorage.getItem('patos-stair-stars')||'[]');if(Array.isArray(saved)){for(let i=0;i<TOTAL&&saved.includes(i);i++)completed.add(i)}}catch{}
let selected=Math.min(completed.size,TOTAL-1),sequenceInput=[],memoryReady=false,timer=null,round=0,mapPage=Math.floor(selected/10);
function duck({face='R',variant='',label='Personaje del dibujo con cabello largo, uñas blancas, traje amarillo y botas de pato'}={}){
 const details={bow:'🎀',nails:'',button:'',stripe:'',earring:''};
 return `<span class="character-sprite" role="img" aria-label="${label}"><span class="character-art ${face==='L'?'mirrored':''}"><img src="assets/duck-costume-girl-boots.png" alt="" draggable="false">${variant?`<span class="costume-detail detail-${variant}" aria-hidden="true">${details[variant]||''}</span>`:''}</span><span class="character-direction" aria-hidden="true">${face==='R'?'→':'←'}</span></span>`;
}
function frontier(){return Math.min(completed.size,TOTAL-1)}
function save(){try{localStorage.setItem('patos-stair-stars',JSON.stringify([...completed]))}catch{}}
function map(){ $('stars').textContent=`⭐ ${completed.size} / ${TOTAL} estrellas`;
 const from=mapPage*10;$('chapter').textContent=`Tramo ${mapPage+1} de 5 · Escalones ${from+1}–${from+10}`;$('previousMap').disabled=mapPage===0;$('nextMap').disabled=mapPage===4;
 $('stairs').innerHTML=levels.slice(from,from+10).map((l,n)=>{const i=from+n;return `<button class="step ${completed.has(i)?'done':''} ${selected===i?'selected':''}" style="--i:${n}" data-level="${i}" ${i>frontier()?'disabled':''} ${selected===i?'aria-current="step"':''} aria-label="Escalón ${i+1}${completed.has(i)?', completado':i>frontier()?', bloqueado':''}">${i+1} · ${typeNames[l.type]}${i===frontier()?`<span class="mini">${duck()}</span>`:''}<span class="mark">${completed.has(i)?'★':i>frontier()?'🔒':'✦'}</span></button>`}).join('');$('stairs').querySelectorAll('button').forEach(b=>b.onclick=()=>openLevel(Number(b.dataset.level),true));}
$('previousMap').onclick=()=>{mapPage=Math.max(0,mapPage-1);map()};$('nextMap').onclick=()=>{mapPage=Math.min(4,mapPage+1);map()};
function feedback(text,kind='retry'){$('feedback').textContent=text;$('feedback').className=`feedback ${kind}`}
function success(){const wasDone=completed.has(selected);completed.add(selected);save();mapPage=Math.floor(frontier()/10);map();feedback(wasDone?'¡Lo resolviste otra vez! Tu estrella sigue brillando.':selected===TOTAL-1?'¡Ganaste la última estrella! ¡Llegaste hasta las nubes!':'¡Lo lograste! ⭐ Ganaste una estrella y tu patito subió.','success');$('next').hidden=false;$('next').textContent=selected===TOTAL-1?'Ver mis 50 estrellas ★':'Subir al siguiente ↑';$('hint').hidden=true;$('activity').querySelectorAll('button').forEach(b=>b.disabled=true);}
function retry(){feedback('¡Casi! Aquí tienes una pista: '+levels[selected].hint+' Puedes intentarlo otra vez.');}
function openLevel(index,focus=false){if(index>frontier()||index<0)return;clearTimeout(timer);round++;if(visited.has(index)||completed.has(index)){const previous=JSON.stringify(levels[index]);do{levels[index]=factory.make(levels[index].type,index)}while(JSON.stringify(levels[index])===previous)}visited.add(index);selected=index;mapPage=Math.floor(index/10);sequenceInput=[];memoryReady=false;map();const l=levels[index];$('levelLabel').textContent=`ESCALÓN ${index+1} DE ${TOTAL} · ${typeNames[l.type].toUpperCase()}`;$('title').textContent=l.title;feedback('');$('next').hidden=true;$('hint').hidden=false;
 if(l.type==='different'){$('instructions').textContent=l.instructions;const total=l.total;$('activity').innerHTML='<div class="duck-grid">'+Array.from({length:total},(_,i)=>`<button class="duck-card" data-answer="${i}" aria-label="Patito ${i+1}${i===l.answer?', '+variantNames[l.variant]:', con traje amarillo de pato'}">${duck({face:l.faces[i],variant:i===l.answer?l.variant:''})}<small>Patito ${i+1}</small></button>`).join('')+'</div>';$('activity').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(Number(b.dataset.answer)===l.answer){b.classList.add('correct');success()}else{b.classList.add('wrong');b.setAttribute('aria-label',b.getAttribute('aria-label')+', ya revisado');retry()}});}
 else if(l.type==='count'){$('instructions').textContent=l.instructions;$('activity').innerHTML='<div class="count-grid" role="group" aria-label="Patos para contar">'+Array.from({length:l.total},(_,i)=>duck({face:l.faces[i],variant:l.decorations[i],label:(l.faces[i]==='R'?'Mira a la derecha':'Mira a la izquierda')+(l.decorations[i]?' con moño':' sin moño')})).join('')+'</div>'+choiceButtons(l);bindChoices(l);}
 else if(l.type==='memory'){$('instructions').textContent=l.instructions;showSequence();}
 else{$('instructions').textContent=l.question;$('activity').innerHTML=(l.clues?'<ul class="clues">'+l.clues.map(c=>'<li>'+c+'</li>').join('')+'</ul>':'')+(l.display?'<div class="puzzle-display">'+l.display+'</div>':'')+choiceButtons(l);bindChoices(l);}
 if(focus)$('title').focus();}
function choiceButtons(l){return '<div class="choices puzzle-choices">'+l.choices.map((value,i)=>`<button class="secondary" data-choice="${i}">${value}</button>`).join('')+'</div>'}
function bindChoices(l){$('activity').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(l.choices[Number(b.dataset.choice)]===l.answer)success();else{retry();b.disabled=true}})}
function showSequence(){clearTimeout(timer);memoryReady=false;sequenceInput=[];const l=levels[selected],thisRound=round;$('activity').innerHTML='<div class="sequence">'+l.sequence.map(d=>`<figure>${duck({face:d})}<figcaption>${d==='R'?'Derecha →':'← Izquierda'}</figcaption></figure>`).join('')+'</div><p class="memory-note">Tienes '+l.seconds+' segundos. Después, el baile se oculta.</p><div class="choices"><button id="remember" class="primary">¡Ya me acuerdo!</button></div>';$('remember').onclick=()=>{if(thisRound!==round)return;clearTimeout(timer);memoryReady=true;memoryAnswer()};timer=setTimeout(()=>{if(thisRound===round&&!memoryReady){memoryReady=true;memoryAnswer()}},l.seconds*1000);}
function memoryAnswer(){const l=levels[selected];$('activity').innerHTML='<div class="sequence covered" aria-label="Patitos ocultos">'+l.sequence.map(()=>'🥚').join(' ')+'</div><p class="memory-note">Repite las '+l.sequence.length+' direcciones '+(l.reverse?'en orden inverso.':'en orden.')+'</p><div class="answer-slots" aria-label="Tu respuesta">'+l.sequence.map((_,i)=>sequenceInput[i]?(sequenceInput[i]==='R'?'→':'←'):'·').join(' ')+'</div><div class="choices memory-choices"><button class="secondary" data-dir="L"><span class="arrow">←</span>Izquierda</button><button class="secondary" data-dir="R"><span class="arrow">→</span>Derecha</button></div><div class="choices" style="margin-top:15px"><button class="secondary" id="again">Ver los patitos otra vez</button></div>';$('again').onclick=()=>{feedback('Mira el orden otra vez, sin prisa.');showSequence()};$('activity').querySelectorAll('[data-dir]').forEach(b=>b.onclick=()=>{if(!memoryReady)return;sequenceInput.push(b.dataset.dir);memoryAnswer();if(sequenceInput.length===l.sequence.length){memoryReady=false;if(sequenceInput.every((v,i)=>v===l.expected[i]))success();else{retry();sequenceInput=[];const thisRound=round;timer=setTimeout(()=>{if(round===thisRound){memoryReady=true;memoryAnswer()}},1000);$('activity').querySelectorAll('[data-dir]').forEach(b=>b.disabled=true)}}});}
$('hint').onclick=()=>feedback('💡 '+levels[selected].hint);$('next').onclick=()=>selected<TOTAL-1?openLevel(selected+1,true):win();
function win(){clearTimeout(timer);round++;$('levelLabel').textContent='AVENTURA COMPLETADA';$('title').textContent='¡Los patos no te ganaron!';$('instructions').textContent='Resolviste los 50 retos de la escalera.';$('activity').innerHTML=`<div class="win"><div class="trophy">🏆</div>${duck()}<h3>¡50 estrellas para ti!</h3><p>Observaste, calculaste, recordaste y resolviste misterios.<br>Puedes tocar cualquier escalón para volver a jugar.</p></div>`;feedback('¡Cuac, cuac! Tu patito está muy orgulloso de ti.','success');$('next').hidden=true;$('hint').hidden=true;$('title').focus();}
openLevel(selected);
